WITH item_metrics AS ( SELECT i.i_item_sk, i.i_item_id, i.i_product_name, i.i_current_price, i.i_class, SUM(sr.sr_return_quantity) AS total_return_qty, SUM(sr.sr_return_amt_inc_tax) AS total_return_amt, AVG(sr.sr_return_amt) AS avg_return_amt, COUNT(DISTINCT s.s_state) AS distinct_states FROM store_returns sr JOIN item i ON sr.sr_item_sk = i.i_item_sk JOIN store s ON sr.sr_store_sk = s.s_store_sk WHERE i.i_category = 'Electronics' GROUP BY i.i_item_sk, i.i_item_id, i.i_product_name, i.i_current_price, i.i_class ) SELECT i_item_sk, i_item_id, i_product_name, i_class, total_return_qty, total_return_amt, avg_return_amt, total_return_amt / NULLIF(i_current_price * total_return_qty,0) AS return_ratio, distinct_states, RANK() OVER (ORDER BY total_return_qty DESC) AS qty_rank FROM item_metrics ORDER BY qty_rank ASC LIMIT 15
